import{z as s,x as o,o as A,c as d,q as t,j as r,D as a,d as B,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"安全与水印","description":"","frontmatter":{"title":"安全与水印","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-safety-watermark.md","filePath":"llm/diff-safety-watermark.md","lastUpdated":1791063341000}'),p={name:"llm/diff-safety-watermark.md"};function f(C,E,D,F,m,h){const l=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="安全与水印" tabindex="-1">安全与水印 <a class="header-anchor" href="#安全与水印" aria-label="Permalink to &quot;安全与水印&quot;">​</a></h1><div class="epigraph"><p>过滤器挡内容，水印管来源；两者都挡不住决心明确的敌手，上线问的不是「能不能防住」，是「失效时谁看见、怎么兜」。</p><footer>—— 据 Fernandez 等 Stable Signature（2023）与 C2PA 内容凭证规范整理</footer></div><p><a href="/llm/diff-fid-pipeline">上一课</a>给质量立了门禁。质量门之外还有两道上线前绕不开的门：输出安全与来源水印。它们都装在第一课解剖的收尾段里，也都有一条共同的纪律：机制的可失效性要被设计，而不是被假设不存在。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>风险在两侧：输入侧提示词可被绕过（同义改写、错字混排、多语言拼接都能绕开关键词表），输出侧违规图像无论提示词如何都要被拦住——所以过滤必须在解码后的像素上再设一道。水印侧的诉求不同：平台要能证明「这张图出自本服务」，用于溯源、追责与内容凭证。常见错误有两个：把提示词过滤当唯一防线；或把水印当防伪加密——它不是安全边界，是概率性溯源信号。缺口是双门过滤加水印管线的工程协议，以及两者失效时的处置路径。</p><h3 id="双门与水印的落点" tabindex="-1">双门与水印的落点 <a class="header-anchor" href="#双门与水印的落点" aria-label="Permalink to &quot;双门与水印的落点&quot;">​</a></h3><ul><li><strong>输入门</strong>：提示词与参考图、控制图同过一道分类器；便宜、低延迟，能挡明显意图，按可绕过预期设计。</li><li><strong>输出门</strong>：解码后像素过图像分类器与哈希库比对（既有违法图像哈希库）；这是真防线，延迟与误杀率都在这里。</li><li><strong>水印</strong>：频域像素水印在收尾段嵌入；内容凭证（C2PA 类）并行写入文件。</li><li><strong>审计账</strong>：提示词、条件集、种子、模型版本、过滤判定全部落盘，支撑申诉与溯源。</li></ul><p><span class="marginnote">哈希库比对可以理解为「指纹黑名单」：给每张图算出一个几乎唯一的指纹串（相同内容算出相同指纹），把已知违规图像的指纹存成库，新图也算指纹去库里查——不用看懂图的内容，只对指纹，所以既快又稳定，缺点是改几个像素就可能换指纹，因此只对「原样传播」的违规图有效。</span></p><p><span class="marginnote">元数据凭证经截图或平台转码即被剥离；频域像素水印抗轻度压缩，但缩放加裁剪加重编码的组合也能洗掉。两条腿互补：元数据给完整凭证，像素水印给元数据被剥后的最后溯源线索。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>安全门按「漏杀与误杀分别定价」配置：漏杀的代价不对称地高，输出门宁可偏严；误杀的代价是正常请求被拒，用申诉通道兜底——每条拒绝给理由码，可申诉复审，误杀样本回流评测集。权重侧的概念擦除只作纵深一层：它伤及相邻良性概念（<a href="/llm/diff-step-distill-tradeoff">蒸馏课</a>讲过学生继承教师），且对新规避手法无自适应；运营上真正可迭代的是外部过滤器，升级不过版。水印固定在收尾段解码之后：对像素做频域嵌入，强度在「抗轻度压缩」与「不可见」之间标定，结果进评测管线回归。</p>',11)),(A(),r(n,null,{default:a(()=>[i(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%EF%BC%9A%E6%8F%90%E7%A4%BA%E8%AF%8D%20%2B%20%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20G1%7B%22%E8%BE%93%E5%85%A5%E9%97%A8%EF%BC%9A%E5%88%86%E7%B1%BB%E5%99%A8%22%7D%0A%20%20G1%20--%3E%7C%E6%8B%A6%7C%20REJ%5B%22%E6%8B%92%E7%BB%9D%20%2B%20%E7%90%86%E7%94%B1%E7%A0%81%20%2B%20%E7%94%B3%E8%AF%89%E5%85%A5%E5%8F%A3%22%5D%0A%20%20G1%20--%3E%7C%E8%BF%87%7C%20LOOP%5B%22%E5%8E%BB%E5%99%AA%E5%BE%AA%E7%8E%AF%E4%B8%8E%E8%A7%A3%E7%A0%81%22%5D%0A%20%20LOOP%20--%3E%20G2%7B%22%E8%BE%93%E5%87%BA%E9%97%A8%EF%BC%9A%E5%9B%BE%E5%83%8F%E5%88%86%E7%B1%BB%20%2B%20%E5%93%88%E5%B8%8C%E6%AF%94%E5%AF%B9%22%7D%0A%20%20G2%20--%3E%7C%E6%8B%A6%7C%20REJ%0A%20%20G2%20--%3E%7C%E8%BF%87%7C%20WM%5B%22%E9%A2%91%E5%9F%9F%E6%B0%B4%E5%8D%B0%E5%B5%8C%E5%85%A5%22%5D%0A%20%20WM%20--%3E%20C2%5B%22%E5%86%99%E5%85%A5%E5%86%85%E5%AE%B9%E5%87%AD%E8%AF%81%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20C2%20--%3E%20OUT%5B%22%E5%87%BA%E5%9B%BE%EF%BC%8C%E5%AE%A1%E8%AE%A1%E8%B4%A6%E8%90%BD%E7%9B%98%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"失效之后走哪条路，和机制本身同样值得画出来：误杀与漏杀的兜底方向相反，一个向用户侧申诉，一个向内部侧回溯。",-1)),(A(),r(n,null,{default:a(()=>[i(l,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E6%9F%90%E6%AC%A1%E5%88%A4%E5%AE%9A%E5%87%BA%E9%94%99%22%5D%20--%3E%20Q%7B%22%E9%94%99%E5%9C%A8%E5%93%AA%E4%B8%80%E4%BE%A7%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%AF%AF%E6%9D%80%EF%BC%9A%E5%A5%BD%E5%9B%BE%E8%A2%AB%E6%8B%A6%22%7C%20APP%5B%22%E7%94%A8%E6%88%B7%E6%8F%90%E4%BA%A4%E7%94%B3%E8%AF%89%20%2B%20%E7%90%86%E7%94%B1%E7%A0%81%22%5D%0A%20%20APP%20--%3E%20RV%5B%22%E4%BA%BA%E5%B7%A5%E5%A4%8D%E5%AE%A1%E6%94%BE%E8%A1%8C%22%5D%0A%20%20RV%20--%3E%20FB%5B%22%E8%AF%AF%E6%9D%80%E6%A0%B7%E6%9C%AC%E5%9B%9E%E6%B5%81%E8%AF%84%E6%B5%8B%E9%9B%86%22%5D%0A%20%20FB%20--%3E%20TUNE%5B%22%E4%B8%8B%E8%BD%AE%E9%98%88%E5%80%BC%E4%B8%8E%E5%88%86%E7%B1%BB%E5%99%A8%E6%A0%87%E5%AE%9A%22%5D%0A%20%20Q%20--%3E%7C%22%E6%BC%8F%E6%9D%80%EF%BC%9A%E5%9D%8F%E5%9B%BE%E6%94%BE%E5%87%BA%22%7C%20AUD%5B%22%E6%9F%A5%E5%AE%A1%E8%AE%A1%E8%B4%A6%EF%BC%9A%E6%8F%90%E7%A4%BA%E8%AF%8D%20%2F%20%E7%A7%8D%E5%AD%90%20%2F%20%E7%89%88%E6%9C%AC%22%5D%0A%20%20AUD%20--%3E%20TRACE%5B%22%E5%9B%9E%E6%BA%AF%E6%9D%A5%E6%BA%90%E5%B9%B6%E5%A4%84%E7%BD%AE%22%5D%0A%20%20TRACE%20--%3E%20UP%5B%22%E8%BF%87%E6%BB%A4%E5%99%A8%E8%A7%84%E5%88%99%E5%8D%87%E7%BA%A7%EF%BC%8C%E4%B8%8D%E8%BF%87%E7%89%88%E7%83%AD%E6%9B%B4%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p>为什么过滤必须双门：输入门看的是意图代理，输出门看的是事实结果；提示词绕过输入门后，像素分类是最后一道。为什么输出门设在解码后而不是潜空间里：违规性主要由像素级语义承载，潜变量上的分类器既不准也不稳定。为什么水印强度不能拉满：嵌入能量与视觉质量是同一张图的预算，拉满会被人眼与评测管线同时发现；标定目标是「社交媒体一次转码后仍可检出」，不是「对抗洗稿后仍可检出」——后者在威胁模型之外。</p><p><span class="marginnote">「频域嵌入」可以想象成不盖可见的章，而是把极淡的墨水按特定纹路撒进整张图的明暗纹理里：每一处都淡到人眼看不出，但用正确钥匙做统计检验时，这些纹路会累加成一个可检出的信号。信号分散在全图而非集中在某个角落，所以轻度压缩磨不掉它，裁掉一小块也还有剩余。</span></p><p>为什么审计账与机制同等重要：过滤器与水印都会失效，失效之后的溯源、申诉与追责全靠落盘的谱系（条件集、种子、版本、判定）。没有审计账，误杀无法申诉、漏杀无法回溯、水印无法作证——机制管当下，账本管事后。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不解决对抗性攻防：水印移除与对抗提示词是持续对抗过程，工程协议保证可检测、可升级、可审计，不是绝对防线。概念擦除的质量代价要过<a href="/llm/diff-fid-pipeline">评测管线</a>的门，不能只看违规率下降。哈希库比对只在有明确法律义务的辖区启用，比对命中走人工复核而非自动处置。安全过滤的延迟计入单价表：输出门的毫秒是每张图的真实成本。最后，过滤器自身的回归要独立于质量回归：拦截率与误杀率分曲线监控，两根曲线混报会让「变严」伪装成「变好」。</p><p><span class="marginnote">为什么混报危险：假设升级过滤器后拦截率从 5% 升到 8%，看似更安全；但若误杀率同时从 0.5% 涨到 3%，说明它在大量错杀正常请求。两根曲线画在同一张总分里，「更严」和「更准」就分不开了——只有分开盯，才能发现这次升级到底是挡住了坏人，还是把好人也挡在了门外。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>过滤双门：输入门挡意图代理，输出门在像素上挡事实结果，后者是真防线。</li><li>误杀走申诉与理由码，漏杀代价更高，阈值向严偏置并回流误杀样本。</li><li>概念擦除只是纵深一层，可迭代的是外部过滤器；升级不过版。</li><li>水印是概率性溯源信号：频域嵌入加内容凭证双腿，按「一次转码仍可检出」标定。</li><li>审计账与机制同等重要：谱系落盘支撑申诉、回溯与作证。</li><li>出处：Fernandez 等 Stable Signature（2023）、C2PA 规范；双门协议据内容安全实践整理。</li></ul>',8))])}const _=s(p,[["render",f]]);export{c as __pageData,_ as default};
